use super::*;
use chrono::{DateTime, TimeZone, Utc};

#[test]
fn signatures_match_the_independent_volcengine_go_sdk_oracle() {
    let at = Utc.with_ymd_and_hms(2026, 10, 9, 8, 30, 15).unwrap();
    // Fixed values from volc-sdk-golang 06f9ef66 GetSignRequest, also
    // pinned by Magpie's TestVolcSignMatchesSDK; never generated by this signer.
    for (region, action, expected) in [
        (
            "cn-beijing",
            "GetCodingPlanUsage",
            "deb80c0cd8bd77768ca40f6d47c7204621c0994428f6ab77e23b76e15dc4c047",
        ),
        (
            "cn-shanghai",
            "GetAFPUsage",
            "8a241be0996c93de4dfcd9e8b1db37494bf63170804fcaebe8380ff7dca2bb23",
        ),
    ] {
        let (auth, date, sha) = sign(
            "AKLTexample",
            "c2VjcmV0LWV4YW1wbGU=",
            region,
            &query(action),
            b"{}",
            at,
        );
        assert_eq!(auth, format!("HMAC-SHA256 Credential=AKLTexample/20261009/{region}/ark/request, SignedHeaders=content-type;host;x-content-sha256;x-date, Signature={expected}"));
        assert_eq!(date, "20261009T083015Z");
        assert_eq!(
            sha,
            "44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a"
        );
    }
}
#[test]
fn signing_normalizes_the_same_instant_to_utc_and_escapes_query_spaces() {
    let east = DateTime::parse_from_rfc3339("2026-10-09T16:30:15+08:00").unwrap();
    let utc = DateTime::parse_from_rfc3339("2026-10-09T08:30:15Z").unwrap();
    assert_eq!(
        sign(
            "a",
            "b",
            "cn-beijing",
            &query("A B/+"),
            b"{}",
            east.with_timezone(&Utc)
        ),
        sign(
            "a",
            "b",
            "cn-beijing",
            &query("A B/+"),
            b"{}",
            utc.with_timezone(&Utc)
        )
    );
    assert_eq!(query("A B/+"), "Action=A%20B%2F%2B&Version=2024-01-01");
}
